// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract Recorder {
    struct Rec { address from; address to; uint256 v; uint256 callCount; uint256 dataLen; }
    mapping(address => Rec) public recs;
    uint256 public total;

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        Rec storage r = recs[to];
        r.from = from;
        r.to = to;
        r.v = v;
        r.callCount += 1;
        r.dataLen = msg.data.length;
        total += 1;
        return true;
    }

    fallback() external payable {
        total += 1;
    }

    function count() external view returns (uint256) { return total; }
    function recOf(address to) external view returns (Rec memory) { return recs[to]; }
}

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        if (tos.length == 0 || tos.length > 5) return;
        if (from == address(0)) return;
        Recorder rec = new Recorder();
        address caddress = address(rec);
        for (uint256 i = 0; i < tos.length; i++) {
            if (tos[i] == address(0) || tos[i] == caddress) return;
        }
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool r) { ok = r; } catch { ok = false; }
        if (!ok) return;
        bool allGood = true;
        for (uint256 i = 0; i < tos.length; i++) {
            Recorder.Rec memory r = rec.recOf(tos[i]);
            if (r.callCount != 1) { allGood = false; break; }
            if (r.from != from || r.to != tos[i] || r.v != v) { allGood = false; break; }
        }
        assertTrue(allGood);
    }
}
